function ensureRecoveryC(v,w){v.v33d1cRecovery=v.v33d1cRecovery||{episodeActive:false,entryCal:null,lastSampleCal:-99999,lastManualWood:null,lowWoodGatherSeasons:0,localWoodExhausted:false,startsEpisode:0,totalStarts:0,lastStartCal:-99999,lastAttemptCal:-99999,lastReason:'NONE',status:'NORMAL'};const s=v.v33d1cRecovery,active=!!v.recoveryState?.active,now=CALC(w);if(active&&!s.episodeActive){s.episodeActive=true;s.entryCal=Number(v.recoveryState?.sinceDay||0)>0?Number(v.recoveryState.sinceDay)*3:now;s.lowWoodGatherSeasons=0;s.localWoodExhausted=false;s.startsEpisode=0;s.lastManualWood=Number(v.recoveryState?.manualWood||0);s.status='RECOVERY';}if(!active&&s.episodeActive){s.episodeActive=false;s.entryCal=null;s.lowWoodGatherSeasons=0;s.localWoodExhausted=false;s.startsEpisode=0;s.lastManualWood=Number(v.recoveryState?.manualWood||0);s.status='NORMAL';}return s;}
