function recoveryEscapePulseC(v,w){const state=ensureRecoveryC(v,w);if(!v.recoveryState?.active){state.status='NORMAL';return false;}const gate=recoveryEscapeGateC(v,w);state.status=gate.ok?'ESCAPE_READY':gate.reason;if(!gate.ok)return false;if(gate.now-Number(state.lastAttemptCal||-99999)<80)return false;return startRecoveryExpansionC(v,w,gate);}
