function dlC(name,text,type='application/json'){const blob=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
const savePrevC=NS.SaveSystem;(function(){const KEY='village-observer-v0-33d1c',fallback=['village-observer-v0-33d1b','village-observer-v0-33d1a','village-observer-v0-33d1','village-observer-v0-33d','village-observer-v0-33c3f','village-observer-v0-33c3'];NS.SaveSystem={save(w){localStorage.setItem(KEY,JSON.stringify(w.serialize()));},load(){let r=localStorage.getItem(KEY);for(const k of fallback)if(!r)r=localStorage.getItem(k);return r?NS.World.from(JSON.parse(r)):null;},export(w){dlC(`village-observer-v033D1C-save-${w.year}y.json`,JSON.stringify(w.serialize()));},exportDevJSON(w){dlC(`village-observer-v033D1C-devlog-${w.telemetry.sessionId}.json`,JSON.stringify(w.telemetry.toJSON(w)));},exportDevCSV(w){const text=w.telemetry.snapshotsCSV(),c=NS.V032E14?.validateCSV?.(text);if(c&&!c.ok)throw new Error(`CSV schema mismatch: expected ${c.columns} columns; bad rows ${c.bad.slice(0,8).join(', ')}`);dlC(`village-observer-v033D1C-snapshots-${w.telemetry.sessionId}.csv`,'\ufeff'+text,'text/csv;charset=utf-8');},async import(file){return NS.World.from(JSON.parse(await file.text()));},async importMap(file){return attachC(await savePrevC.importMap(file));},async importScenario(file){return attachC(await savePrevC.importScenario(file));},exportScenario(w,meta=null){const x=NS.V032E14?.scenarioWrapper?.(w,meta);if(!x)return savePrevC.exportScenario(w,meta);x.meta={...x.meta,intendedVersion:'0.33D1C'};x.world.testScenario={...x.meta};if(x.world.v32e11)x.world.v32e11.scenario={...x.meta};dlC(`village-observer-v033D1C-scenario-${x.meta.id}.json`,JSON.stringify(x));return x;}};})();

