if(NS.UI){const setPrevC=NS.UI.prototype.setWorld,headPrevC=NS.UI.prototype.renderHeader,contentPrevC=NS.UI.prototype.renderVillageContent,statsPrevC=NS.UI.prototype.renderStats,renderPrevC=NS.UI.prototype.render,codexPrevC=NS.UI.prototype.renderCodex;NS.UI.prototype.setWorld=function(w){return setPrevC.call(this,attachC(w));};NS.UI.prototype.renderHeader=function(){headPrevC.call(this);document.title='Village Observer V0.33D1C';const b=document.getElementById('versionBadge');if(b)b.innerHTML='Village Observer · <strong>V0.33D1C</strong>';const st=this.q?.('runtimeStatus');if(st)st.textContent=`✓ V0.33D1C 전쟁 관측·Recovery Escape 안정화 · 주거 3/5/8 · 도로 ×0.62 · 유지 0.5% · Tech ${Number(NS.V033D1B?.techCostTotal||6315)}K`;};NS.UI.prototype.renderVillageContent=function(){const r=contentPrevC.call(this);renderRecentC(this);return r;};NS.UI.prototype.renderStats=function(){return statsPrevC.call(this);};NS.UI.prototype.render=function(){const r=renderPrevC.call(this);renderRecentC(this);return r;};NS.UI.prototype.renderCodex=function(){const r=codexPrevC.call(this),el=this.q?.('codexContent');if(el&&!el.querySelector('.v33d1c-note')){const note=document.createElement('div');note.className='codex-note v33d1c-note';note.innerHTML='<strong>V0.33D1C 전쟁·복구 기준</strong><br>1국 대 1국은 <b>단독전쟁</b>, 어느 한 Side라도 복수 국가가 참전하면 <b>합동전쟁</b>으로 표시합니다. 전쟁 결과는 A/B 문자만 쓰지 않고 실제 국가 구성을 함께 표시합니다. Recovery가 2년 이상 장기 고착되고 내부 자원·주거 해결이 불가능한 경우에만 제한적 복구용 개척을 허용합니다.';(el.querySelector('[data-page="war"]')||el).insertAdjacentElement('afterbegin',note);}return r;};}
if(typeof document!=='undefined'){const st=document.createElement('style');st.textContent=`.v33d1c-war-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;margin:8px 0 10px}.v33d1c-war-summary span{padding:7px 8px;border-radius:8px;background:rgba(255,255,255,.04);font-size:11px}.v33d1c-mini strong{color:#e9f1ff}@media(max-width:760px){.v33d1c-war-summary{grid-template-columns:1fr}}`;document.head.appendChild(st);}

if(Array.isArray(NS.PATCH_NOTES)&&!NS.PATCH_NOTES.some(x=>x.version==='V0.33D1C'))NS.PATCH_NOTES.unshift({version:'V0.33D1C',date:'2026-09-30',title:'War Observer + Recovery Escape Stabilization',summary:'D1B 자연주행에서 확인된 A/B측 결과 가독성, 누적 점령 0 표시, 델마형 장기 Recovery-Expansion deadlock, 독립전쟁 용어 혼동을 정리합니다. D1B의 건설·주거·도로·기술 기준은 유지합니다.',sections:[['전쟁 결과 가독성',['전쟁 카드에 A측/B측과 실제 참가국 구성을 함께 표시합니다.','종전 결과는 “A측 승리” 대신 “에브 승리 (A측)” 또는 “벨른 + 델마 승리 (A측)”처럼 실제 승리국을 먼저 표시합니다.','국가별 최근 전쟁은 해당 국가 관점의 승리/패배와 소속 Side를 함께 표시합니다.']],['점령 기록 수정',['War History의 실제 저장 객체 history33A와 D1A/B의 잘못된 v33aHistory 참조를 통합합니다.','TILE_OCCUPIED33 / TILE_LIBERATED33 telemetry를 사용해 과거 전쟁의 고유 점령·최대 동시 점령·수도 점령을 가능한 범위에서 보강합니다.','통계 전쟁패널에서 현재 점령과 누적 점령 발생을 별도 수치로 표시합니다.']],['Recovery Expansion Escape V1',['Recovery가 720 calendar-day 이상 지속되고 실제 Survival 상태가 아니며 식량 30일 이상·평균 건강 55 이상일 때만 탈출 개척을 검토합니다.','목재 부족 상태에서 수동채집이 여러 분기 사실상 실패하거나, 장기 주거 부족을 내부 건설로 해결하지 못하는 경우에만 RECOVERY_EXPANSION을 허용합니다.','복구용 개척은 한 번에 1개, Recovery episode당 최대 2회이며 일반 확장보다 작은 2인 개척대와 별도 최소 비용을 사용합니다.','목재 고착은 목재가 풍부한 인접지, 주거 고착은 건축 잠재력이 높은 인접지를 우선합니다. Recovery 자체는 유지되며 실제 지표가 회복되어야 기존 조건으로 종료됩니다.']],['전쟁 명칭',['1국 대 1국 전쟁의 UI 명칭을 독립전쟁에서 단독전쟁으로 변경합니다.','어느 한 Side라도 복수 국가가 참전하면 합동전쟁으로 표시합니다.','기존 independentConcurrentDeclarations33D 등 내부 telemetry 키는 저장/CSV 호환성을 위해 유지합니다.']],['기준 유지',['D1B의 건설 노동량, 유지보수 분기 0.5%, 주거 3/5/8, 단일 도로 ×0.62, 기술비 6,315 Knowledge를 그대로 유지합니다.','War Intent, Intel 100% proxy, Operational Reachability, Coalition military access, Persistent Engagement와 Formation lifecycle도 변경하지 않습니다.','실제 PREPARING 군비·비축·집결은 다음 D2 범위로 유지합니다.']]]});
